    // Legs & curled elf shoes
    [-0.11, 0.11].forEach((lx) => {
      const leg = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.06, 0.28, 6), darkMat);
      leg.position.set(lx, 0.16, 0);
