    cone2.position.y = 1.6;
    cone2.castShadow = true;
    pine.add(cone2);

    const cone3 = new THREE.Mesh(new THREE.ConeGeometry(0.5, 0.8, 7), roofGreenMat);
    cone3.position.y = 2.2;
    cone3.castShadow = true;
