import * as THREE from 'three';

/**
 * Snow particle system — 3000 falling snowflakes with sway animation.
 * Uses BufferGeometry + Points for high performance.
 */

// Generate a soft circular dot texture via canvas
function createSnowflakeTexture() {
  const size = 32;
  const canvas = document.createElement('canvas');
  canvas.width = size;
  canvas.height = size;
  const ctx = canvas.getContext('2d');

  // Radial gradient: white center fading to transparent edge
  const gradient = ctx.createRadialGradient(
    size / 2, size / 2, 0,
    size / 2, size / 2, size / 2
  );
  gradient.addColorStop(0, 'rgba(255, 255, 255, 1)');
  gradient.addColorStop(0.4, 'rgba(255, 255, 255, 0.8)');
  gradient.addColorStop(1, 'rgba(255, 255, 255, 0)');

  ctx.fillStyle = gradient;
  ctx.fillRect(0, 0, size, size);

  const texture = new THREE.CanvasTexture(canvas);
  return texture;
}

export function createSnow(scene) {
  const PARTICLE_COUNT = 3000;

  // --- Position buffer ---
  const positions = new Float32Array(PARTICLE_COUNT * 3);

  // --- Per-particle data (plain arrays for the update loop) ---
  const velocities = new Array(PARTICLE_COUNT);
  const swayPhases = new Array(PARTICLE_COUNT);

  // Initialize particles with random positions, velocities, and sway phases
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    // Random X in [-50, 50]
    positions[i * 3] = (Math.random() - 0.5) * 100;
    // Random Y in [0, 40]
    positions[i * 3 + 1] = Math.random() * 40;
    // Random Z in [-18, 40] (clears the air over the distant elf village)
    positions[i * 3 + 2] = -18 + Math.random() * 58;

    // Fall speed between 2 and 5
    velocities[i] = 2 + Math.random() * 3;
    // Random sway phase so particles don't all sway in sync
    swayPhases[i] = Math.random() * Math.PI * 2;
  }

  // --- Geometry ---
  const geometry = new THREE.BufferGeometry();
  geometry.setAttribute('position', new THREE.BufferAttribute(positions, 3));

  // --- Material with soft dot texture ---
  const texture = createSnowflakeTexture();

  const material = new THREE.PointsMaterial({
    color: 0xffffff,
    size: 0.3,
    transparent: true,
    opacity: 0.8,
    sizeAttenuation: true,
    depthWrite: false,
    map: texture,
    blending: THREE.AdditiveBlending
  });

  // --- Points mesh ---
  const snow = new THREE.Points(geometry, material);
  // Snow doesn't cast/receive shadows (it's a particle system)
  scene.add(snow);

  // --- Animation update ---
  function update(delta, elapsed) {
    for (let i = 0; i < PARTICLE_COUNT; i++) {
      const idx = i * 3;

      // Fall downward
      positions[idx + 1] -= velocities[i] * delta;

      // Horizontal sway
      positions[idx] += Math.sin(elapsed * 0.5 + swayPhases[i]) * 0.02;

      // Reset particle when it drops below the ground
      if (positions[idx + 1] < 0) {
        positions[idx] = (Math.random() - 0.5) * 100;       // new random X
        positions[idx + 1] = 35 + Math.random() * 5;         // reset Y near top
        positions[idx + 2] = -18 + Math.random() * 58;      // keep clear of elf village
      }
    }

    // Flag the position attribute for GPU upload
    geometry.attributes.position.needsUpdate = true;
  }

  return { update };
}

import * as THREE from 'three';

/**
 * Creates a single Christmas tree with blinking lights
 * @param {number} height - Overall height scale of the tree
 * @param {number} x - X position
 * @param {number} z - Z position
 * @returns {{ group: THREE.Group, lights: Array }} The tree group and its light data
 */
function makeTree(height, x, z) {
    const group = new THREE.Group();
    group.position.set(x, 0, z);

    // --- Trunk ---
    const trunkGeo = new THREE.CylinderGeometry(
        0.2 * height, // top radius
        0.3 * height, // bottom radius
        height * 0.3, // height
        8             // radial segments (low-poly)
    );
    const trunkMat = new THREE.MeshToonMaterial({ color: 0x6B3A2A });
    const trunk = new THREE.Mesh(trunkGeo, trunkMat);
    trunk.position.y = (height * 0.3) / 2; // sit on ground
    trunk.castShadow = true;
    trunk.receiveShadow = true;
    group.add(trunk);

    // --- Crown: 3 stacked cone layers ---
    const crownBase = height * 0.3; // top of trunk

    // Bottom cone layer
    const bottomConeGeo = new THREE.ConeGeometry(height * 0.6, height * 0.5, 8);
    const bottomConeMat = new THREE.MeshToonMaterial({ color: 0x1a7a2a });
    const bottomCone = new THREE.Mesh(bottomConeGeo, bottomConeMat);
    bottomCone.position.y = crownBase + height * 0.25;
    bottomCone.castShadow = true;
    group.add(bottomCone);

    // Middle cone layer
    const midConeGeo = new THREE.ConeGeometry(height * 0.45, height * 0.4, 8);
    const midConeMat = new THREE.MeshToonMaterial({ color: 0x228B22 });
    const midCone = new THREE.Mesh(midConeGeo, midConeMat);
    midCone.position.y = crownBase + height * 0.5;
    midCone.castShadow = true;
    group.add(midCone);

    // Top cone layer
    const topConeGeo = new THREE.ConeGeometry(height * 0.3, height * 0.35, 8);
    const topConeMat = new THREE.MeshToonMaterial({ color: 0x2ea043 });
    const topCone = new THREE.Mesh(topConeGeo, topConeMat);
    topCone.position.y = crownBase + height * 0.75;
    topCone.castShadow = true;
    group.add(topCone);

    // --- Star on top ---
    const starGeo = new THREE.SphereGeometry(0.15, 8, 6);
    const starMat = new THREE.MeshBasicMaterial({ color: 0xFFD700 });
    const star = new THREE.Mesh(starGeo, starMat);
    star.position.y = crownBase + height * 0.75 + height * 0.35 / 2 + 0.15;
    group.add(star);

    // --- Blinking lights ---
    // Reference cone layers for placing lights on their surfaces
    const coneLayers = [
        { cone: bottomCone, radius: height * 0.6, h: height * 0.5, yBase: crownBase + height * 0.0 },
        { cone: midCone,    radius: height * 0.45, h: height * 0.4, yBase: crownBase + height * 0.3 },
        { cone: topCone,    radius: height * 0.3,  h: height * 0.35, yBase: crownBase + height * 0.575 },
    ];

    const lightColors = [0xff0000, 0x0066ff, 0xffff00, 0x00ff00, 0xff00ff, 0x00ffff];
    const numLights = 8 + Math.floor(Math.random() * 5); // 8-12 lights
    const lights = [];

    for (let i = 0; i < numLights; i++) {
        // Pick a random cone layer
        const layer = coneLayers[Math.floor(Math.random() * coneLayers.length)];

        // Random angle around the cone
        const angle = Math.random() * Math.PI * 2;
        // Random height fraction along the cone (0 = base, 1 = tip)
        const t = Math.random() * 0.85; // avoid the very tip
        // Cone radius shrinks linearly from base to tip
        const r = layer.radius * (1 - t) * 0.85; // slightly inset so lights sit on surface

        const lx = Math.cos(angle) * r;
        const lz = Math.sin(angle) * r;
        const ly = layer.yBase + t * layer.h;

        const lightGeo = new THREE.SphereGeometry(0.08, 6, 4);
        const color = lightColors[i % lightColors.length];
        const lightMat = new THREE.MeshBasicMaterial({
            color: color,
            transparent: true,
            opacity: 1.0,
        });

        const lightMesh = new THREE.Mesh(lightGeo, lightMat);
        lightMesh.position.set(lx, ly, lz);
        group.add(lightMesh);

        // Store light data for animation
        lights.push({
            mesh: lightMesh,
            material: lightMat,
            phaseOffset: Math.random() * Math.PI * 2, // random phase for async twinkling
        });
    }

    return { group, lights };
}

/**
 * Creates multiple Christmas trees with twinkling lights and adds them to the scene.
 * @param {THREE.Scene} scene
 * @returns {{ update(delta: number, elapsed: number): void }}
 */
export function createTrees(scene) {
    // Tree placement positions and heights
    const treeConfigs = [
        { x:   8, z:   3, height: 3.0 },
        { x:  10, z:  -2, height: 2.5 },
        { x: -10, z:   2, height: 3.5 },
        { x:  -8, z:   6, height: 2.8 },
        { x:   6, z: -10, height: 4.0 },
        { x: -12, z:  -4, height: 3.2 },
        { x:  14, z:   5, height: 2.2 },
    ];

    // Collect all lights across all trees for the update loop
    const allLights = [];

    for (const cfg of treeConfigs) {
        const { group, lights } = makeTree(cfg.height, cfg.x, cfg.z);
        scene.add(group);
        allLights.push(...lights);
    }

    // Return the animation updater for twinkling lights
    return {
        /**
         * Update twinkling lights each frame
         * @param {number} delta - Time since last frame (seconds)
         * @param {number} elapsed - Total elapsed time (seconds)
         */
        update(delta, elapsed) {
            for (const light of allLights) {
                // Sinusoidal intensity modulation with per-light phase offset
                light.material.opacity =
                    0.3 + 0.7 * Math.abs(Math.sin(elapsed * 2 + light.phaseOffset));
            }
        },
    };
}

import * as THREE from 'three';

/**
 * Creates Santa's Workshop from primitive shapes.
 * Cartoon cel-shaded style using MeshToonMaterial throughout.
 */
export function createWorkshop(scene) {
  const workshop = new THREE.Group();

  // ───────────────────────────────────────────────
  // 1. Main Building — Walls
  // ───────────────────────────────────────────────
  const wallGeo = new THREE.BoxGeometry(10, 5, 7);
  const wallMat = new THREE.MeshToonMaterial({ color: 0x8b5e3c });
  const walls = new THREE.Mesh(wallGeo, wallMat);
  walls.position.y = 2.5; // half-height so bottom sits on ground
  walls.castShadow = true;
  walls.receiveShadow = true;
  workshop.add(walls);

  // ───────────────────────────────────────────────
  // 1b. Roof — 4-sided cone (pyramid)
  // ───────────────────────────────────────────────
  const roofGeo = new THREE.ConeGeometry(8, 3.5, 4);
  const roofMat = new THREE.MeshToonMaterial({ color: 0xaa2222 });
  const roof = new THREE.Mesh(roofGeo, roofMat);
  // Rotate 45° around Y so the square base aligns with the rectangular walls
  roof.rotation.y = Math.PI / 4;
  roof.position.y = 5 + 3.5 / 2; // on top of walls
  roof.castShadow = true;
  roof.receiveShadow = true;
  workshop.add(roof);

  // ───────────────────────────────────────────────
  // 2. Door
  // ───────────────────────────────────────────────
  const doorGeo = new THREE.BoxGeometry(1.8, 3, 0.15);
  const doorMat = new THREE.MeshToonMaterial({ color: 0x5c3a1a });
  const door = new THREE.Mesh(doorGeo, doorMat);
  // Front face of wall is at z = 3.5, door sticks out slightly
  door.position.set(0, 1.5, 3.5 + 0.08);
  door.castShadow = true;
  workshop.add(door);

  // Doorknob
  const knobGeo = new THREE.SphereGeometry(0.12, 8, 6);
  const knobMat = new THREE.MeshToonMaterial({ color: 0xffd700 });
  const knob = new THREE.Mesh(knobGeo, knobMat);
  knob.position.set(0.6, 1.5, 3.5 + 0.2);
  workshop.add(knob);

  // ───────────────────────────────────────────────
  // 3. Windows (two, flanking the door)
  // ───────────────────────────────────────────────
  const windowGeo = new THREE.BoxGeometry(1.5, 1.5, 0.15);
  const windowMat = new THREE.MeshToonMaterial({
    color: 0xffcc44,
    emissive: 0xffaa00,
    emissiveIntensity: 0.8,
  });

  const windowPositions = [
    { x: -2.8, label: 'left' },
    { x: 2.8, label: 'right' },
  ];

  windowPositions.forEach((wp) => {
    // Window pane
    const win = new THREE.Mesh(windowGeo, windowMat);
    win.position.set(wp.x, 2.8, 3.5 + 0.08);
    workshop.add(win);

    // Point light behind each window for warm light spill
    const light = new THREE.PointLight(0xffaa00, 0.5, 10);
    light.position.set(wp.x, 2.8, 3.0);
    workshop.add(light);
  });

  // ───────────────────────────────────────────────
  // 4. Chimney (Animated cartoon wiggle, squash & stretch & smoke)
  // ───────────────────────────────────────────────
  const chimneyGroup = new THREE.Group();
  // Pivot at the roof level on the right side of the roof
  chimneyGroup.position.set(3, 4.75, -1);

  const chimneyGeo = new THREE.BoxGeometry(1, 2.5, 1);
  const chimneyMat = new THREE.MeshToonMaterial({ color: 0x993333 });
  const chimney = new THREE.Mesh(chimneyGeo, chimneyMat);
  chimney.position.y = 1.25; // center so bottom sits on pivot
  chimney.castShadow = true;
  chimneyGroup.add(chimney);

  // Chimney top rim / lip
  const rimGeo = new THREE.BoxGeometry(1.2, 0.2, 1.2);
  const rimMat = new THREE.MeshToonMaterial({ color: 0x772222 });
  const rim = new THREE.Mesh(rimGeo, rimMat);
  rim.position.y = 2.45;
  rim.castShadow = true;
  chimneyGroup.add(rim);

  // Snow on rim
  const rimSnowGeo = new THREE.BoxGeometry(1.25, 0.1, 1.25);
  const rimSnowMat = new THREE.MeshToonMaterial({ color: 0xffffff });
  const rimSnow = new THREE.Mesh(rimSnowGeo, rimSnowMat);
  rimSnow.position.y = 2.55;
  chimneyGroup.add(rimSnow);

  // Warm glowing hearth opening
  const hearthGlowGeo = new THREE.CircleGeometry(0.35, 8);
  const hearthGlowMat = new THREE.MeshBasicMaterial({
    color: 0xff6600,
    side: THREE.DoubleSide,
  });
  const hearthGlow = new THREE.Mesh(hearthGlowGeo, hearthGlowMat);
  hearthGlow.rotation.x = -Math.PI / 2;
  hearthGlow.position.y = 2.56;
  chimneyGroup.add(hearthGlow);

  workshop.add(chimneyGroup);

  // Dynamic rising smoke puffs
  const smokePuffCount = 7;
  const smokePuffs = [];
  const smokeGeo = new THREE.SphereGeometry(0.24, 7, 7);

  for (let i = 0; i < smokePuffCount; i++) {
    const puffMat = new THREE.MeshToonMaterial({
      color: 0xd8d8d8,
      transparent: true,
      opacity: 0.65,
    });
    const puff = new THREE.Mesh(smokeGeo, puffMat);
    workshop.add(puff);

    smokePuffs.push({
      mesh: puff,
      progress: i / smokePuffCount,
      speed: 0.35 + Math.random() * 0.1,
      swayOffset: Math.random() * Math.PI * 2,
      driftX: 0.2 + (Math.random() - 0.5) * 0.3,
      driftZ: -0.1 + (Math.random() - 0.5) * 0.3,
      maxHeight: 3.8 + Math.random() * 1.0,
    });
  }

  // ───────────────────────────────────────────────
  // 5. Sign — "Santa's Workshop" above the door
  // ───────────────────────────────────────────────
  const signCanvas = document.createElement('canvas');
  signCanvas.width = 512;
  signCanvas.height = 128;
  const ctx = signCanvas.getContext('2d');

  // Wooden background
  ctx.fillStyle = '#8B5E3C';
  ctx.fillRect(0, 0, 512, 128);

  // Subtle darker border
  ctx.strokeStyle = '#5c3a1a';
  ctx.lineWidth = 8;
  ctx.strokeRect(4, 4, 504, 120);

  // Text shadow for depth
  ctx.font = 'bold 52px serif';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillStyle = '#660000';
  ctx.fillText("Santa's Workshop", 258, 67);

  // Main text — festive red with gold feel
  ctx.fillStyle = '#ff2222';
  ctx.fillText("Santa's Workshop", 256, 65);

  // Gold outline on text
  ctx.strokeStyle = '#ffd700';
  ctx.lineWidth = 1.5;
  ctx.strokeText("Santa's Workshop", 256, 65);

  const signTexture = new THREE.CanvasTexture(signCanvas);
  const signGeo = new THREE.PlaneGeometry(3, 0.8);
  const signMat = new THREE.MeshToonMaterial({
    map: signTexture,
    side: THREE.DoubleSide,
  });
  const sign = new THREE.Mesh(signGeo, signMat);
  sign.position.set(0, 4.2, 3.55);
  workshop.add(sign);

  // ───────────────────────────────────────────────
  // 6. Snow on Roof
  // ───────────────────────────────────────────────
  const snowGeo = new THREE.BoxGeometry(10.5, 0.3, 7.5);
  const snowMat = new THREE.MeshToonMaterial({ color: 0xffffff });
  const snow = new THREE.Mesh(snowGeo, snowMat);
  // Sit on top of the wall edges, just below where the roof starts
  snow.position.y = 5.15;
  snow.receiveShadow = true;
  workshop.add(snow);

  // ───────────────────────────────────────────────
  // Position the entire workshop group
  // ───────────────────────────────────────────────
  workshop.position.set(-2, 0, -5);

  scene.add(workshop);

  // ───────────────────────────────────────────────
  // Animation update loop for chimney and smoke
  // ───────────────────────────────────────────────
  return {
    /**
     * @param {number} delta - Frame time in seconds
     * @param {number} elapsed - Total run time in seconds
     */
    update(delta, elapsed) {
      // 1. Cartoon sway and wiggle (tilting side to side and forward/back)
      const swayZ = Math.sin(elapsed * 4.0) * 0.08;
      const swayX = Math.cos(elapsed * 3.0) * 0.05;
      chimneyGroup.rotation.z = swayZ;
      chimneyGroup.rotation.x = swayX;

      // 2. Cartoon squash & stretch (chugging rhythm like a steam engine furnace)
      const chug = Math.sin(elapsed * 8.0);
      const stretch = Math.max(0, chug) * 0.1;
      chimneyGroup.scale.y = 1.0 + stretch;
      chimneyGroup.scale.x = 1.0 - stretch * 0.5;
      chimneyGroup.scale.z = 1.0 - stretch * 0.5;

      // 3. Hearth fire flicker
      hearthGlowMat.color.setHex(Math.sin(elapsed * 12) > 0 ? 0xff7700 : 0xff3300);

      // 4. Emerging smoke position following the swaying chimney top
      const topOffsetLocal = new THREE.Vector3(0, 2.55 * chimneyGroup.scale.y, 0);
      topOffsetLocal.applyEuler(chimneyGroup.rotation);
      const topPos = chimneyGroup.position.clone().add(topOffsetLocal);

      // 5. Dynamic rising smoke puffs
      for (let i = 0; i < smokePuffs.length; i++) {
        const p = smokePuffs[i];
        p.progress += delta * p.speed;
        if (p.progress >= 1.0) {
          p.progress = 0;
        }

        const pr = p.progress;
        p.mesh.position.y = topPos.y + pr * p.maxHeight;
        p.mesh.position.x =
          topPos.x + Math.sin(elapsed * 2.5 + p.swayOffset) * 0.35 * pr + p.driftX * pr * 1.5;
        p.mesh.position.z =
          topPos.z + Math.cos(elapsed * 2.0 + p.swayOffset) * 0.25 * pr + p.driftZ * pr * 1.5;

        const s = 0.8 + pr * 2.0;
        p.mesh.scale.set(s, s * 0.85, s);
        p.mesh.material.opacity = (1.0 - pr) * 0.65;
      }
    },
  };
}
